const item = $input.item;
let text = item.json.output || "";

// State definitions
let hasOrder = false; let orderData = {};
let hasRegister = false; let registerData = {};
let hasQuote = false; let quoteData = {};
let hasMeetingIntent = false; 
let hasBookingConfirmation = false; let meetingData = {};
let hasCancellation = false; let targetClientName = "";
let hasReschedule = false; let rescheduleData = {};
let hasBuyingIntent = false; 

let extractionError = false; // NEW: Global flag to track AI JSON failures

// NEW: Safe Parsing Helper Function
function parseJSONSafely(jsonString) {
    try {
        return { success: true, data: JSON.parse(jsonString) };
    } catch (e) {
        extractionError = true; // Trigger the fallback
        return { success: false, data: {} };
    }
}

// 1. Check for ORDER tag
const orderMatch = text.match(/\|\|\|ORDER:(\{.*?\})\|\|\|/);
if (orderMatch) {
    const parsed = parseJSONSafely(orderMatch[1]);
    if (parsed.success) { hasOrder = true; orderData = parsed.data; }
    text = text.replace(/\|\|\|ORDER:(\{.*?\})\|\|\|/g, '').trim();
}

// 2. Check for REGISTER tag
const registerMatch = text.match(/\|\|\|REGISTER:(\{.*?\})\|\|\|/);
if (registerMatch) {
    const parsed = parseJSONSafely(registerMatch[1]);
    if (parsed.success) { hasRegister = true; registerData = parsed.data; }
    text = text.replace(/\|\|\|REGISTER:(\{.*?\})\|\|\|/g, '').trim();
}

// 3. Check for QUOTE tag
const quoteMatch = text.match(/\|\|\|QUOTE:(\{.*?\})\|\|\|/);
if (quoteMatch) {
    const parsed = parseJSONSafely(quoteMatch[1]);
    if (parsed.success) { hasQuote = true; quoteData = parsed.data; }
    text = text.replace(/\|\|\|QUOTE:(\{.*?\})\|\|\|/g, '').trim();
}

// 4. Check for BOOKING Confirmation
const bookingMatch = text.match(/\|\|\|BOOKING:(\{.*?\})\|\|\|/);
if (bookingMatch) {
    const parsed = parseJSONSafely(bookingMatch[1]);
    if (parsed.success) { hasBookingConfirmation = true; meetingData = parsed.data; }
    text = text.replace(/\|\|\|BOOKING:(\{.*?\})\|\|\|/g, '').trim();
}

// 5. Check for Cancellations
const cancelMatch = text.match(/\|\|\|CANCEL:(\{.*?\})\|\|\|/);
if (cancelMatch) {
    const parsed = parseJSONSafely(cancelMatch[1]);
    if (parsed.success) { hasCancellation = true; targetClientName = parsed.data.targetClientName; }
    text = text.replace(/\|\|\|CANCEL:(\{.*?\})\|\|\|/g, '').trim();
}

// 6. Check for Rescheduling
const reschedMatch = text.match(/\|\|\|RESCHEDULE:(\{.*?\})\|\|\|/);
if (reschedMatch) {
    const parsed = parseJSONSafely(reschedMatch[1]);
    if (parsed.success) { hasReschedule = true; rescheduleData = parsed.data; }
    text = text.replace(/\|\|\|RESCHEDULE:(\{.*?\})\|\|\|/g, '').trim();
}

// 7. Check for Basic Text Intents (No JSON parsing required)
if (text.includes('|||INTENT:B2B_PRICING|||')) {
    hasBuyingIntent = true;
    text = text.replace(/\|\|\|INTENT:B2B_PRICING\|\|\|/g, '').trim();
}
if (text.includes('|||MEETING_INTENT|||')) {
    hasMeetingIntent = true;
    text = text.replace(/\|\|\|MEETING_INTENT\|\|\|/g, '').trim();
}

// FALLBACK HANDLER: If the AI broke the JSON, force an escalation
if (extractionError) {
    // Append the escalation tag so the 'Did AI Escalate?' node catches it
    text += " |||ESCALATE|||";
}

// Final cleanup (Removes any accidental markdown blocks left by the AI)
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

return {
    json: {
        output: text,
        hasOrder: hasOrder,
        orderData: orderData,
        hasRegister: hasRegister,
        registerData: registerData,
        hasQuote: hasQuote,
        quoteData: quoteData,
        hasMeetingIntent: hasMeetingIntent,
        hasBookingConfirmation: hasBookingConfirmation,
        meetingData: meetingData,
        hasCancellation: hasCancellation,
        hasReschedule: hasReschedule,
        targetClientName: targetClientName,
        rescheduleData: rescheduleData,
        hasBuyingIntent: hasBuyingIntent,
        from: $('Extract Message Data').first().json.from,
        sessionId: $('Extract Message Data').first().json.sessionId
    }
};

