// 1. Fetch data from the Parse Order Intent node
const parseIntentItem = $('Parse Order Intent').first().json;
const quoteData = parseIntentItem.quoteData || parseIntentItem || {};

// 2. Extract numeric parameters safely with defaults
const quantity = Number(quoteData.quantity) || 1;
const unitPrice = Number(quoteData.unit_price) || 0;
const discountPrcnt = Number(quoteData.discount_prcnt) || 0;

// 3. Calculate Prices
const subtotal = unitPrice * quantity;
const discountAmount = subtotal * (discountPrcnt / 100);
const discountedPrice = Math.round((subtotal - discountAmount) * 100) / 100;

// 4. Output complete merged object for n8n
return {
  json: {
    ...quoteData,
    discount_prcnt: discountPrcnt,
    discounted_price: discountedPrice,
    total_price: subtotal
  }
};

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  if (items[i].binary && items[i].binary.data) {
    // Read the PDF from n8n's filesystem memory
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    // Convert to base64 and attach to JSON
    items[i].json.pdf_base64 = buffer.toString('base64');
  }
}

return items;

